package com.soprasteria.g4it.backend.external.ecologits.business;

import com.soprasteria.g4it.backend.exception.ExternalApiException;
import com.soprasteria.g4it.backend.external.ecologits.client.EcologitsClient;
import com.soprasteria.g4it.backend.external.ecologits.model.request.EcoEstimationRequestRest;
import com.soprasteria.g4it.backend.external.ecologits.model.response.EcoEstimationResponseRest;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;

/**
 * Service in charge of calling the EcoLogits calculation engine to estimate the environmental
 * impacts of a Large Language Model (LLM) usage.
 */
@Service
@AllArgsConstructor
@Slf4j
public class EcologitsService {

    public static final String ECOLOGITS_ENGINE = "EcoLogits";

    private final EcologitsClient ecologitsClient;

    /**
     * Estimate the environmental impacts of an LLM inference call using EcoLogits.
     *
     * @param provider           the LLM provider (e.g. openai, mistralai, anthropic...)
     * @param model              the model name (e.g. gpt-4o-mini)
     * @param outputTokenCount   number of tokens generated by the model
     * @param electricityMixZone ISO 3166-1 alpha-3 zone code for the electricity mix (nullable, defaults to world average)
     * @return the EcoLogits estimation response
     * @throws ExternalApiException when EcoLogits returns an error or is unreachable
     */
    public EcoEstimationResponseRest runEstimation(final String provider,
                                                   final String model,
                                                   final int outputTokenCount,
                                                   final String electricityMixZone) {

        EcoEstimationRequestRest request = EcoEstimationRequestRest.builder()
                .provider(provider)
                .modelName(model)
                .outputTokenCount(outputTokenCount)
                .electricityMixZone(electricityMixZone)
                .build();

        return ecologitsClient.runEstimation(request);
    }
}